var groups: [12][12]usize = undefined;
var lengths: [12]usize = @splat(0);
var count: usize = 0;
for (words, 0..) |_, i| {
    var g: usize = 0;
    while (g < count and !std.mem.eql(u32, &keys[i], &keys[groups[g][0]])) : (g += 1) {}
    if (g == count) count += 1;
    groups[g][lengths[g]] = i;
